-- Financial Home: initial PostgreSQL / Flyway migration.
-- UUIDs are generated by the application; timestamps use timestamptz.

CREATE TABLE users (
    id uuid PRIMARY KEY,
    email varchar(255) NOT NULL UNIQUE,
    password_hash varchar(255),
    status varchar(20) NOT NULL DEFAULT 'ACTIVE',
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_status_chk CHECK (status IN ('ACTIVE', 'INACTIVE', 'BLOCKED'))
);

CREATE TABLE people (
    id uuid PRIMARY KEY,
    user_id uuid UNIQUE REFERENCES users(id),
    name varchar(100) NOT NULL,
    last_name varchar(100),
    sex varchar(20),
    CONSTRAINT people_sex_chk CHECK (sex IS NULL OR sex IN ('FEMALE', 'MALE', 'UNSPECIFIED'))
);

CREATE TABLE households (
    id uuid PRIMARY KEY,
    name varchar(150) NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'ACTIVE',
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT households_status_chk CHECK (status IN ('ACTIVE', 'ARCHIVED'))
);

CREATE TABLE household_members (
    id uuid PRIMARY KEY,
    household_id uuid NOT NULL REFERENCES households(id),
    person_id uuid NOT NULL REFERENCES people(id),
    family_role varchar(30),
    access_role varchar(20) NOT NULL DEFAULT 'NO_ACCESS',
    joined_at timestamptz NOT NULL DEFAULT now(),
    left_at timestamptz,
    CONSTRAINT household_members_uk UNIQUE (household_id, person_id),
    CONSTRAINT household_members_access_role_chk CHECK (access_role IN ('ADMIN', 'MEMBER', 'NO_ACCESS')),
    CONSTRAINT household_members_family_role_chk CHECK (family_role IS NULL OR family_role IN
      ('FATHER','MOTHER','SON','DAUGHTER','GRANDFATHER','GRANDMOTHER','BROTHER','SISTER','PARTNER','GUARDIAN','OTHER')),
    CONSTRAINT household_members_dates_chk CHECK (left_at IS NULL OR left_at >= joined_at)
);
CREATE INDEX household_members_person_idx ON household_members(person_id);

CREATE TABLE household_invitations (
    id uuid PRIMARY KEY,
    household_id uuid NOT NULL REFERENCES households(id),
    invited_user_id uuid NOT NULL REFERENCES users(id),
    invited_by_user_id uuid NOT NULL REFERENCES users(id),
    proposed_role varchar(20) NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'PENDING',
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    responded_at timestamptz,
    CONSTRAINT invitations_role_chk CHECK (proposed_role IN ('ADMIN', 'MEMBER')),
    CONSTRAINT invitations_status_chk CHECK (status IN ('PENDING', 'ACCEPTED', 'REJECTED', 'EXPIRED')),
    CONSTRAINT invitations_dates_chk CHECK (expires_at > created_at),
    CONSTRAINT invitations_distinct_users_chk CHECK (invited_user_id <> invited_by_user_id)
);
CREATE UNIQUE INDEX pending_invitations_uk ON household_invitations(household_id, invited_user_id)
    WHERE status = 'PENDING';

CREATE TABLE financial_accounts (
    id uuid PRIMARY KEY,
    name varchar(100) NOT NULL,
    type varchar(30) NOT NULL,
    owner_type varchar(20) NOT NULL,
    owner_person_id uuid REFERENCES people(id),
    owner_household_id uuid REFERENCES households(id),
    currency varchar(3) NOT NULL DEFAULT 'MXN',
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT accounts_type_chk CHECK (type IN ('BANK', 'CASH', 'SAVINGS', 'DIGITAL_WALLET')),
    CONSTRAINT accounts_owner_chk CHECK (
        (owner_type = 'PERSON' AND owner_person_id IS NOT NULL AND owner_household_id IS NULL)
        OR (owner_type = 'HOUSEHOLD' AND owner_household_id IS NOT NULL AND owner_person_id IS NULL)
    ),
    CONSTRAINT accounts_currency_chk CHECK (currency ~ '^[A-Z]{3}$')
);
CREATE INDEX accounts_owner_person_idx ON financial_accounts(owner_person_id);
CREATE INDEX accounts_owner_household_idx ON financial_accounts(owner_household_id);

CREATE TABLE household_accounts (
    id uuid PRIMARY KEY,
    account_id uuid NOT NULL REFERENCES financial_accounts(id),
    household_id uuid NOT NULL REFERENCES households(id),
    linked_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT household_accounts_uk UNIQUE (account_id, household_id)
);
CREATE INDEX household_accounts_household_idx ON household_accounts(household_id);

CREATE TABLE cards (
    id uuid PRIMARY KEY,
    account_id uuid NOT NULL REFERENCES financial_accounts(id),
    name varchar(100) NOT NULL,
    type varchar(20) NOT NULL,
    last_four_digits varchar(4),
    status varchar(20) NOT NULL DEFAULT 'ACTIVE',
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT cards_type_chk CHECK (type IN ('PHYSICAL', 'DIGITAL')),
    CONSTRAINT cards_status_chk CHECK (status IN ('ACTIVE', 'INACTIVE', 'BLOCKED')),
    CONSTRAINT cards_last_four_chk CHECK (last_four_digits IS NULL OR last_four_digits ~ '^[0-9]{4}$'),
    CONSTRAINT cards_id_account_uk UNIQUE (id, account_id)
);

CREATE TABLE financial_transactions (
    id uuid PRIMARY KEY,
    household_id uuid NOT NULL REFERENCES households(id),
    type varchar(20) NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'DRAFT',
    description varchar(200) NOT NULL,
    recorded_by_person_id uuid NOT NULL REFERENCES people(id),
    performed_by_person_id uuid NOT NULL REFERENCES people(id),
    reversed_transaction_id uuid UNIQUE REFERENCES financial_transactions(id),
    transaction_at timestamptz NOT NULL,
    recorded_at timestamptz NOT NULL DEFAULT now(),
    confirmed_at timestamptz,
    CONSTRAINT transactions_type_chk CHECK (type IN ('INCOME', 'EXPENSE', 'TRANSFER', 'OPENING_BALANCE', 'REVERSAL')),
    CONSTRAINT transactions_status_chk CHECK (status IN ('DRAFT', 'CONFIRMED')),
    CONSTRAINT transactions_confirmation_chk CHECK (
        (status = 'DRAFT' AND confirmed_at IS NULL)
        OR (status = 'CONFIRMED' AND confirmed_at IS NOT NULL)
    ),
    CONSTRAINT transactions_reversal_chk CHECK ((type = 'REVERSAL') = (reversed_transaction_id IS NOT NULL)),
    CONSTRAINT transactions_self_reversal_chk CHECK (reversed_transaction_id IS NULL OR reversed_transaction_id <> id)
);
CREATE INDEX transactions_household_date_idx ON financial_transactions(household_id, transaction_at DESC);
CREATE INDEX confirmed_transactions_household_idx ON financial_transactions(household_id, transaction_at DESC)
    WHERE status = 'CONFIRMED';

CREATE TABLE transaction_entries (
    id uuid PRIMARY KEY,
    transaction_id uuid NOT NULL REFERENCES financial_transactions(id),
    account_id uuid NOT NULL REFERENCES financial_accounts(id),
    payment_method varchar(30),
    card_id uuid,
    amount numeric(18,2) NOT NULL,
    CONSTRAINT entries_nonzero_amount_chk CHECK (amount <> 0),
    CONSTRAINT entries_payment_method_chk CHECK (payment_method IS NULL OR payment_method IN
        ('CASH', 'TRANSFER', 'DEBIT_CARD', 'OTHER')),
    CONSTRAINT entries_card_method_chk CHECK (
        card_id IS NULL OR (payment_method IS NOT NULL AND payment_method = 'DEBIT_CARD')
    ),
    CONSTRAINT entries_card_account_fk FOREIGN KEY (card_id, account_id) REFERENCES cards(id, account_id)
);
CREATE INDEX entries_transaction_idx ON transaction_entries(transaction_id);
CREATE INDEX entries_account_idx ON transaction_entries(account_id);


-- Initial iteration requirements:
-- 1) Before confirmation, validate transaction types and entry signs in the backend.
--    Internal transfers must sum to zero and use matching currencies.
-- 2) Confirmed transactions are immutable: prevent backend UPDATE/DELETE operations,
--    then enforce this with SQL permissions or triggers before real multiuser use.
-- 3) Verify household membership and account authorization.
-- 4) Row Level Security, email invitations, and administrative auditing remain
--    pending requirements before production.
-- 5) Do not count linked personal account balances as shared household funds.
